import{_ as a,c as r,o,a3 as t}from"./chunks/framework.Dk6sf0Ip.js";const f=JSON.parse('{"title":"Verificación y Cierre de la Orden de Trabajo (OT)","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/OT_Verificacion.md","filePath":"flows/Mantenimiento/OT_Verificacion.md","lastUpdated":1759260532000}'),i={name:"flows/Mantenimiento/OT_Verificacion.md"};function n(s,e,l,d,c,u){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="verificacion-y-cierre-de-la-orden-de-trabajo-ot" tabindex="-1">Verificación y Cierre de la Orden de Trabajo (OT) <a class="header-anchor" href="#verificacion-y-cierre-de-la-orden-de-trabajo-ot" aria-label="Permalink to &quot;Verificación y Cierre de la Orden de Trabajo (OT)&quot;">​</a></h1><h2 id="ot-verificacion" tabindex="-1">OT Verificación <a class="header-anchor" href="#ot-verificacion" aria-label="Permalink to &quot;OT Verificación&quot;">​</a></h2><p>Este es el último paso en el ciclo de vida de la Orden de Trabajo. El objetivo es que un supervisor o gerente <strong>valide</strong> que el mantenimiento se completó según lo solicitado y que todos los registros de materiales y tiempos se cargaron correctamente en el sistema.</p><h3 id="objetivo-de-la-verificacion" tabindex="-1">Objetivo de la Verificación <a class="header-anchor" href="#objetivo-de-la-verificacion" aria-label="Permalink to &quot;Objetivo de la Verificación&quot;">​</a></h3><ul><li>Asegurar que todas las tareas listadas (incluyendo <strong>Montajes, Rotaciones o Reparaciones de cubiertas</strong>) fueron ejecutadas.</li><li>Confirmar que el vehículo está listo para volver a la operación.</li><li><strong>Cerrar</strong> la OT para que todos los costos (mano de obra, repuestos, cubiertas) se imputen al vehículo y se actualice el inventario.</li></ul><h3 id="formulario-de-verificacion" tabindex="-1">Formulario de Verificación <a class="header-anchor" href="#formulario-de-verificacion" aria-label="Permalink to &quot;Formulario de Verificación&quot;">​</a></h3><table><tr><td>Campo </td><td>Propósito </td><td>Puntos de Verificación (Enfoque en Cubiertas) </td></tr><tr><td><strong>ID / Solicitud N° / Fecha de la OT</strong></td><td>Datos de referencia de la Orden de Trabajo. </td><td>Confirmar que la OT que se va a cerrar es la correcta. </td></tr><tr><td><strong>Referencia / Tarea a realizar</strong></td><td>Acciones que se debían ejecutar. </td><td>Verificar que las acciones fueron completadas. </td></tr><tr><td><strong>Observaciones de verificación</strong></td><td>Espacio para que el verificador deje notas. </td><td><strong>CRÍTICO:</strong> Utilice este espacio para dejar constancia de la conformidad con el trabajo. </td></tr><tr><td><strong>Adjuntos (PDF)</strong></td><td>Documentación física escaneada. </td><td>Revisar que, si aplica, se adjuntaron fotos de la reparación o informes de taller. </td></tr></table><h3 id="flujo-de-cierre-y-validacion" tabindex="-1">Flujo de Cierre y Validación <a class="header-anchor" href="#flujo-de-cierre-y-validacion" aria-label="Permalink to &quot;Flujo de Cierre y Validación&quot;">​</a></h3><p>El proceso de cierre de la OT requiere utilizar los botones de acción del sistema:</p><table><tr><td>Botón </td><td>Propósito en el Flujo </td><td>Instrucciones para el Gerente/Supervisor </td></tr><tr><td><strong>GUARDAR</strong></td><td><strong>Guardar como Borrador.</strong></td><td>Utilice si necesita pausar la verificación o si requiere enviar a corregir un dato antes de validar la OT. </td></tr><tr><td><strong>SIGUIENTE</strong></td><td><strong>Validación y Cierre Final.</strong></td><td><strong>Úselo únicamente cuando esté conforme o se vuelve a abrir</strong> con el trabajo y los registros. Al pulsar <strong>SIGUIENTE</strong>, la OT se marca como <strong>&quot;Finalizada&quot;</strong> o <strong>&quot;Verificada&quot;</strong>. Esto finaliza la imputación de costos y libera la unidad. </td></tr><tr><td><strong>CERRAR</strong></td><td><strong>Finaliza la sesión.</strong></td><td>Cierra la ventana sin guardar cambios pendientes o avanzar la OT. </td></tr></table><h3 id="reapertura-de-la-ot-abrir-nuevamente" tabindex="-1">Reapertura de la OT (Abrir nuevamente) <a class="header-anchor" href="#reapertura-de-la-ot-abrir-nuevamente" aria-label="Permalink to &quot;Reapertura de la OT (Abrir nuevamente)&quot;">​</a></h3><p>En caso de que, durante la verificación, se detecten errores, tareas incompletas o faltantes en la documentación, el supervisor/gerente debe <strong>abrir nuevamente la OT (20.2.02)</strong>.</p><h4 id="situaciones-que-requieren-reapertura" tabindex="-1">Situaciones que requieren reapertura <a class="header-anchor" href="#situaciones-que-requieren-reapertura" aria-label="Permalink to &quot;Situaciones que requieren reapertura&quot;">​</a></h4><ul><li>La reparación de cubiertas no fue realizada correctamente.</li><li>El vehículo aún presenta la falla reportada.</li><li>No se cargaron materiales, repuestos o tiempos en el sistema.</li><li>Los comprobantes o adjuntos obligatorios no fueron agregados.</li></ul><h4 id="flujo-al-reabrir" tabindex="-1">Flujo al reabrir <a class="header-anchor" href="#flujo-al-reabrir" aria-label="Permalink to &quot;Flujo al reabrir&quot;">​</a></h4><ol><li>El supervisor selecciona la opción <strong>Abrir nuevamente</strong>.</li><li>La OT vuelve al estado <strong>“Abierta”</strong>, quedando disponible para que el Operario/Área de Mantenimiento realice las correcciones.</li><li>Una vez corregido, se repite el proceso de <strong>Verificación de la OT (20.2.04)</strong>.</li><li>Si esta vez todo es correcto, se procede al <strong>Cierre final</strong> y al archivo correspondiente.</li></ol><blockquote><p><strong>Nota:</strong> La reapertura de una OT debe quedar documentada en las observaciones, indicando el motivo del rechazo y las acciones a corregir.</p></blockquote>',17)]))}const m=a(i,[["render",n]]);export{f as __pageData,m as default};
